class Solution {
    const double EPS = 1e-5;
    bool dfs(vector<double>& nums) {
        if (nums.size() == 1) return abs(nums[0] - 24.0) < EPS;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                vector<double> nextNums;
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) nextNums.push_back(nums[k]);
                }
                double a = nums[i], b = nums[j];
                vector<double> candidates = {a + b, a - b, a * b};
                if (abs(b) > EPS) candidates.push_back(a / b);
                for (double cand : candidates) {
                    nextNums.push_back(cand);
                    if (dfs(nextNums)) return true;
                    nextNums.pop_back();
                }
            }
        }
        return false;
    }
