class Solution {
    private static final double EPS = 1e-5;
    public boolean judgePoint24(int[] cards) {
        List<Double> nums = new ArrayList<>();
        for (int c : cards) nums.add((double) c);
        return dfs(nums);
    }
    private boolean dfs(List<Double> nums) {
        if (nums.size() == 1) return Math.abs(nums.get(0) - 24.0) < EPS;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                List<Double> nextNums = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) nextNums.add(nums.get(k));
                }
                double a = nums.get(i), b = nums.get(j);
                List<Double> candidates = new ArrayList<>(Arrays.asList(a + b, a - b, a * b));
                if (Math.abs(b) > EPS) candidates.add(a / b);
                for (double cand : candidates) {
                    nextNums.add(cand);
                    if (dfs(nextNums)) return true;
                    nextNums.remove(nextNums.size() - 1);
                }
            }
        }
        return false;
    }
}

var judgePoint24 = function(cards) {
    const EPS = 1e-5;
    function dfs(nums) {
        if (nums.length === 1) return Math.abs(nums[0] - 24.0) < EPS;
        const n = nums.length;
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                if (i === j) continue;
                const nextNums = [];
                for (let k = 0; k < n; k++) {
                    if (k !== i && k !== j) nextNums.push(nums[k]);
                }
                const a = nums[i], b = nums[j];
                const candidates = [a + b, a - b, a * b];
                if (Math.abs(b) > EPS) candidates.push(a / b);
                for (const cand of candidates) {
                    nextNums.push(cand);
                    if (dfs(nextNums)) return true;
                    nextNums.pop();
                }
            }
        }
        return false;
    }
    return dfs(cards.map(Number));
};
